SELECT COUNT(*) FROM external_sync_job
WHERE provider='google' AND job_type='MAPPING_SYNC' AND business_id=#{businessId}
  AND status IN (0, 1) AND deleted_at=0

SELECT id, business_id, CAST(request_payload AS CHAR) AS request_payload, status,
    error_message, requested_by, started_at, finished_at, created_at
FROM external_sync_job
WHERE provider='google' AND job_type='MAPPING_SYNC' AND business_id=#{businessId}
  AND deleted_at=0
ORDER BY created_at DESC, id DESC LIMIT #{offset}, #{limit}

